WITH exploded AS (SELECT id, service, host, log_ts, k, attr_value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) li AS k, attr_value) SELECT DATE_TRUNC('DAY', log_ts) AS activity_day, service, COUNT(*) AS row_count, COUNT_IF(k = 'region') AS region_events, GROUPING_ID() AS grouping_level FROM exploded GROUP BY ROLLUP (DATE_TRUNC('DAY', log_ts), service) HAVING COUNT_IF(k = 'region') >= 1;
